#ifndef GGL_MATCALC
#define GGL_MATCALC

struct matrix {
	char *name;
	double **mat;	/* normal access via mat[][] */
	double *fast;	/* allows fast access to matrix */
	int row;
	int col;
	int dim_row;
	int dim_col;
};


/* writes some error on stderr */
void m_error (
	const char *procname,
	struct matrix *m1, 
	struct matrix *m2,
	struct matrix *m3,
	int *row, 
	int *col);

/* initializes a matrix structure */
struct matrix * m_init (int row, int col);

/* initializes the name of a matrix */
int m_name (struct matrix *m, const char *newname);

/* initializes a matrix structure with name */
struct matrix * m_init_name (int row, int col, char *newname);

/* frees the structure matrix */
void m_free (struct matrix *m);


/* resizes the matrix without new memory allocation 
 * sets all values to zero if set_zero == TRUE
 */
int m_resize (struct matrix *m, 
		   int row, int col, int set_zero);


/* fill one element at position (row, col) with value */
int m_fill (struct matrix *m,
		 int row, int col, double value);

/* fill all elements of row  with value */
int m_fill_row (struct matrix *m,
		     int row, double value);

/* fill all elements of column col  with value */
int m_fill_col (struct matrix *m,
		     int col, double value);

/* copies upper part to lower part */
int m_fillsym (struct matrix *m);

/* fills matrix completely with zero */
int m_zero (struct matrix *m);

/* fills one row of matrix with zero */
int m_zero_row (struct matrix *m,	int row);

/* makes the matrix to a unit matrix */
int m_unit (struct matrix *m);

/* fills all elements of matrix with value */
int m_set (struct matrix *m, double value);

/* fills all elements with random values in the range 0 - fac */
int m_random (struct matrix *m, double fac);

/* deep copy from source to target */
int m_copy (struct matrix *source,
		 struct matrix *target);

/* ????????? */
int m_pushup (struct matrix *m);
int m_pushdown (struct matrix *m);


int m_max_col (
	struct matrix *m,
	const int col,
	double *max,
	int *row)
;
int m_min_col (
	struct matrix *m,
	const int col,
	double *min,
	int *row)
;
int m_max (
	struct matrix *m,
	double *max,
	int *row,
	int *col)
;
int m_min (
	struct matrix *m,
	double *min,
	int *row,
	int *col)
;
int m_absmax (
	struct matrix *m,
	double *max,
	int *row,
	int *col)
;
int m_write (
	FILE *fpout,
	struct matrix *m,
	const int fmt1,
	const int fmt2,
	int n,
	const int tr,
	const int title)
;
int m_writefmt (
	FILE *fpout,
	struct matrix *m,
	const char * fmt,
	int n,
	const int tr,
	const int title)
;
int m_write_filled (
	FILE *fpout,
	struct matrix *m,
	const int tr,
	double nearlyzero)
;
int m_writebin (
	FILE *fpout,
	struct matrix *m)
;
int m_writebin2 (
	char * fname, 
	struct matrix *m)
;
int m_readbin (
	FILE *fpin,
	struct matrix **m)
;
int m_readbin2 (
	char * fname, 
	struct matrix **m)
;
int m_readascii(
	char *fname, 
	struct matrix **m, 
	int row2read,
	int col2read)
;

int m_add (
	struct matrix *m1,
	struct matrix *m2,
	struct matrix *m_res)
;
int m_sub (
	struct matrix *m1,
	struct matrix *m2,
	struct matrix *m_res)
;
int m_mult (
	struct matrix *m1,
	const int m1tr,
	struct matrix *m2,
	const int m2tr,
	struct matrix *m_res)
;
int m_multx (
	struct matrix *m,
	double scalar,
	struct matrix *m_res)
;
double m_trace (struct matrix *m)
;
int m_trans (
	struct matrix *m,
	struct matrix *m_res)
;
int m_atpa1 (
	struct matrix *a,
	struct matrix *p,
	struct matrix *atpa)
;
int m_det (
        struct matrix *m, 
        double *det)
;

int m_pivot (
	struct matrix *m,
	int row,
	int col)
;
int m_inv (struct matrix *m)
;
int m_cholesky_decomposition (struct matrix *m)
;
int m_choleskyinv (struct matrix *m)
;
double m_sym_check (struct matrix *m)
;
int m_add_block (
	struct matrix *m,
	struct matrix *block,
	int row,
	int col)
;
int m_pick_block (
	struct matrix *m,
	struct matrix *block,
	int row,
	int col,
	int drow,
	int dcol)
;
int m_del_row (
	struct matrix *m,
	int row)
;
int m_del_col (
	struct matrix *m,
	int col)
;
int m_polynom_approx (
	struct matrix *data,
	int col_x,
	int col_y,
        int col_w,
	const int col_app,
	const int col_res,
	const int row_beg,
	const int row_end,
	const int degree,
	double x0,
	double *dummy,
	struct matrix *coeff,
	struct matrix *qxx,
	double *s0)
;

double m_polynom_interpol (
	struct matrix *coeff,
        int num_coeff,
	const double dx)
;

int m_separate_sym(
	struct matrix *m, 
	struct matrix *sym, 
	struct matrix *asym)
;
#endif
